import numpy as np

grid = np.array([
    [0, 0, 0, 0, 0, 0, 9, 8, 8, 8, 0, 9, 0, 0],
    [0, 8, 0, 0, 0, 0, 0, 0, 9, 0, 0, 0, 0, 0],
