    [8, 0, 9, 0, 8, 8, 0, 0, 0, 0, 9, 9, 9, 0],
    [0, 9, 8, 0, 0, 8, 0, 0, 0, 0, 0, 0, 0, 0]
])

def find_endpoints(grid):
    """Mark 1 for endpoint cells (only 1 neighbor), 2 for corner cells (2 orthogonal neighbors forming L), 3 otherwise."""
    rows, cols = grid.shape
    result = np.zeros_like(grid, dtype=int)

    def bfs_component(start_r, start_c, target_val):
        visited = set()
        queue = [(start_r, start_c)]
        component = []

        while queue:
            r, c = queue.pop(0)
            if (r, c) not in visited:
                visited.add((r, c))
                component.append((r, c))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr, nc] == target_val and (nr, nc) not in visited:
                            queue.append((nr, nc))

        return component

    # Process each component
    visited_global = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r, c] != 0 and (r, c) not in visited_global:
                comp = bfs_component(r, c, grid[r, c])

                for rr, cc in comp:
                    # Count orthogonal neighbors (not diagonal)
                    n_neighbors = 0
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr, nc] == grid[rr, cc]:
                                n_neighbors += 1

                    if n_neighbors == 0:
                        result[rr, cc] = 1  # Isolated point
                    elif n_neighbors == 1:
                        result[rr, cc] = 2  # Endpoint
                    else:
                        result[rr, cc] = 3  # Junction/internal

    return result

output = find_endpoints(grid)
print("Endpoint/Corner markers:")
for row in output:
    print(row)

print("\nJSON format:")
print(output.tolist())

