def mark_component_shape(grid):
    """Mark: 1 for corner/L-shape (2 orthogonal neighbors forming angle), 2 for straight line segment."""
    rows, cols = grid.shape
    result = np.zeros_like(grid, dtype=int)

    visited = set()

    def bfs_component(start_r, start_c, target_val):
        queue = [(start_r, start_c)]
        component = []

        while queue:
            r, c = queue.pop(0)
            if (r, c) not in visited:
                visited.add((r, c))
                component.append((r, c))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr, nc] == target_val and (nr, nc) not in visited:
                            queue.append((nr, nc))

        return component

    for r in range(rows):
        for c in range(cols):
            if grid[r, c] != 0 and (r, c) not in visited:
                comp = bfs_component(r, c, grid[r, c])

                # Build adjacency info
                adj = {}
                for rr, cc in comp:
                    neighbors = []
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr, nc] == grid[rr, cc]:
                            neighbors.append((nr, nc))
                    adj[(rr, cc)] = len(neighbors)

                # Check if it's a corner vs straight line
                for rr, cc in comp:
                    n_neighbors = adj[(rr, cc)]
                    neighbors_list = []
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr, nc] == grid[rr, cc]:
                            neighbors_list.append((nr, nc))

                    if n_neighbors == 2:
                        # Check if they're in opposite directions (straight line) or perpendicular (L-shape)
                        n1 = neighbors_list[0][0] - rr
                        d1 = neighbors_list[0][1] - cc
                        n2 = neighbors_list[1][0] - rr
                        d2 = neighbors_list[1][1] - cc

                        # Opposite?
                        opposite = (n1 == -n2 and d1 == -d2)

                        if not opposite:
                            result[rr, cc] = 1  # Corner/L-shape
                        else:
                            result[rr, cc] = 2  # Straight line

                    elif n_neighbors == 1:
                        result[rr, cc] = 3  # Endpoint

                    elif n_neighbors > 2:
                        result[rr, cc] = 4  # Junction
                break

    return result

