    """Mark 1 for cells that have at least one non-zero neighbor of a DIFFERENT value."""
    rows, cols = grid.shape
    result = np.zeros_like(grid, dtype=int)

    values = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r, c] != 0:
